import type {
  IsoTimestamp,
  OrgId,
  SubscriptionId,
  TenantScoped,
  Timestamps,
} from "./common";

export type PlanId = "free" | "starter" | "growth" | "enterprise";

export const PLAN_IDS: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export type BillingInterval = "monthly" | "annual";

export type SubscriptionStatus =
  | "trialing"
  | "active"
  | "past_due"
  | "canceled";

export interface Subscription extends Timestamps, TenantScoped {
  readonly id: SubscriptionId;
  readonly plan: PlanId;
  readonly interval: BillingInterval;
  readonly status: SubscriptionStatus;
  readonly seats: number;
  readonly currentPeriodStart: IsoTimestamp;
  readonly currentPeriodEnd: IsoTimestamp;
  readonly cancelAt: IsoTimestamp | null;
}

/** The resource dimensions every plan caps. Adding a field here ripples into
 *  `PLAN_LIMITS`, `BillingService`, the usage UI and the limit guards. */
export type LimitedResource =
  | "seats"
  | "projects"
  | "issuesPerProject"
  | "storageMb"
  | "apiRequestsPerHour"
  | "webhooks";

/** Result of a single quota check, returned by `BillingService.checkLimit`. */
export interface LimitCheck {
  readonly resource: LimitedResource;
  readonly plan: PlanId;
  readonly limit: number;
  readonly used: number;
  readonly remaining: number;
  readonly exceeded: boolean;
}

export interface Invoice extends Timestamps, TenantScoped {
  readonly id: string;
  readonly number: string;
  readonly amountCents: number;
  readonly currency: string;
  readonly periodStart: IsoTimestamp;
  readonly periodEnd: IsoTimestamp;
  readonly paidAt: IsoTimestamp | null;
}

export interface BillingSummary {
  readonly orgId: OrgId;
  readonly subscription: Subscription;
  readonly checks: readonly LimitCheck[];
  readonly upcomingInvoiceCents: number;
}

import { z } from "zod";
import type { PlanId } from "@/types/billing";
import { orgIdSchema } from "./common";

export const planIdSchema = z.enum(["free", "starter", "growth", "enterprise"]);

export const billingIntervalSchema = z.enum(["monthly", "annual"]);

export const subscriptionStatusSchema = z.enum([
  "trialing",
  "active",
  "past_due",
  "canceled",
]);

export const limitedResourceSchema = z.enum([
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
]);

export const changePlanSchema = z.object({
  orgId: orgIdSchema,
  plan: planIdSchema,
  interval: billingIntervalSchema.default("monthly"),
});

export const updateSeatsSchema = z.object({
  orgId: orgIdSchema,
  seats: z.number().int().min(1).max(10_000),
});

export const cancelSubscriptionSchema = z.object({
  orgId: orgIdSchema,
  reason: z.string().max(500).optional(),
  cancelImmediately: z.boolean().default(false),
});

const _planParity: PlanId = "growth" satisfies z.infer<typeof planIdSchema>;
void _planParity;

export type ChangePlanInput = z.infer<typeof changePlanSchema>;
export type UpdateSeatsInput = z.infer<typeof updateSeatsSchema>;
export type CancelSubscriptionInput = z.infer<typeof cancelSubscriptionSchema>;

/**
 * All quota meters for the organization.
 *
 * Must call (do not reimplement): getPlanLimits
 */
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { getPlanLimits } from "@/config/plan-limits";
import { formatDate } from "@/lib/date";
import type { BillingSummary, LimitedResource } from "@/types/billing";
import type { ReactElement } from "react";
import { UsageMeter } from "./usage-meter";

export type UsagePanelProps = { summary: BillingSummary };

/** Human labels for the quota dimensions, in the order the panel shows them. */
export const RESOURCE_LABELS: Readonly<Record<LimitedResource, string>> = {
  seats: "Seats",
  projects: "Projects",
  issuesPerProject: "Issues per project",
  storageMb: "Storage (MB)",
  apiRequestsPerHour: "API requests / hour",
  webhooks: "Webhooks",
};

const RESOURCE_ORDER: readonly LimitedResource[] = [
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
];

export function UsagePanel(props: UsagePanelProps): ReactElement | null {
  const { summary } = props;
  // The subscription says which plan; the plan table says what it includes.
  const limits = getPlanLimits(summary.subscription.plan);

  const byResource = new Map(
    summary.checks.map((check) => [check.resource, check]),
  );

  return (
    <Card padded>
      <CardHeader>
        <CardTitle>Usage on the {limits.plan} plan</CardTitle>
      </CardHeader>

      <CardContent>
        <div className="space-y-3">
          {RESOURCE_ORDER.map((resource) => {
            const check = byResource.get(resource);
            if (check === undefined) return null;
            return (
              <UsageMeter
                key={resource}
                check={check}
                label={RESOURCE_LABELS[resource]}
              />
            );
          })}
        </div>

        <p className="mt-3 text-xs text-neutral-500">
