 * Calendar arithmetic for recurring issues.
 *
 * An occurrence is a calendar day in the rule's own IANA time zone, so the
 * logic works on `YYYY-MM-DD` strings and leaves wall-clock conversion to
 * `Intl`, which knows about daylight-saving transitions.
 */
import type { RecurrenceCadence, RecurringIssue } from "@/types/recurring-issue";

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

/** A midnight-UTC `Date` for a `YYYY-MM-DD` string; avoids the 1900 two-digit-year quirk. */
function utcDate(date: string): Date {
  const value = new Date(0);
  value.setUTCFullYear(
    Number(date.slice(0, 4)),
    Number(date.slice(5, 7)) - 1,
    Number(date.slice(8, 10)),
  );
  return value;
}

/** True for a real `YYYY-MM-DD` calendar date; `2026-02-30` is rejected. */
export function isCalendarDate(value: string): boolean {
  if (!DATE_PATTERN.test(value)) return false;
  const date = utcDate(value);
  return date.toISOString().slice(0, 10) === value;
}

/** True when the runtime knows `timezone` as an IANA zone. */
export function isKnownTimeZone(timezone: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: timezone });
    return true;
  } catch {
    return false;
  }
}

/** The calendar day `instant` falls on in `timezone`, as `YYYY-MM-DD`. */
export function localDateOf(instant: Date, timezone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);
  const pick = (type: "year" | "month" | "day"): string =>
    parts.find((part) => part.type === type)?.value ?? "";
  return `${pick("year")}-${pick("month")}-${pick("day")}`;
}

/** ISO weekday of a `YYYY-MM-DD` date: 1 = Monday … 7 = Sunday. */
export function isoWeekdayOf(date: string): number {
  const sundayBased = utcDate(date).getUTCDay();
  return sundayBased === 0 ? 7 : sundayBased;
}

/** Adds (or subtracts) whole calendar days to a `YYYY-MM-DD` date. */
export function addDays(date: string, days: number): string {
  const value = utcDate(date);
  value.setUTCDate(value.getUTCDate() + days);
  return value.toISOString().slice(0, 10);
}

/**
 * The latest occurrence of `rule` that has started by `now`, or `null` when
 * none has started yet.
 *
 * Occurrence day D has started once local time in the rule's zone reaches
 * 00:00 on D, so the latest started day is simply today's local date. A
 * weekly rule then steps back to the most recent day with its weekday. Either
 * way the answer is `null` if it falls before `startsOn`.
 */
export function latestOccurrenceOn(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "timezone" | "startsOn">,
  now: Date,
): string | null {
  const today = localDateOf(now, rule.timezone);
  const candidate = occurrenceCandidate(rule.cadence, rule.weekday, today);
  if (candidate === null || candidate < rule.startsOn) return null;
  return candidate;
}

function occurrenceCandidate(
  cadence: RecurrenceCadence,
  weekday: number | null,
  today: string,
): string | null {
  if (cadence === "daily") return today;
  if (weekday === null) return null;
  return addDays(today, -((isoWeekdayOf(today) - weekday + 7) % 7));
}

