/**
 * Files one ordinary issue for each recurring-issue rule whose latest started
 * occurrence has not been filed yet, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): can, isArchived, latestOccurrenceOn, createIssue
 */
import { createLogger } from "@/lib/logger";
import { latestOccurrenceOn } from "@/lib/recurrence";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import * as issueService from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/**
 * One pass over every live rule. A rule that fails is counted and left as it
 * was, so the next run retries it and no other rule is held up.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if (await fileDueOccurrence(rule, now)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Returns true when an issue was created for the rule. */
async function fileDueOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<boolean> {
  const occurrence = latestOccurrenceOn(rule, now);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    throw new Error(`Project ${rule.projectId} was not found`);
  }
  // Left unchanged: once the project is restored, the next run files the
  // then-latest occurrence.
  if (isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (creator === null || creator.status !== "active") {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  const actor: Actor = {
    userId: rule.createdBy,
    orgId: rule.orgId,
    role: creator.role,
  };
  if (!can(actor, "issue:create", projectResource(project))) {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  const assignee =
    rule.assigneeId === null
      ? null
      : await memberRepo.findMember(rule.orgId, rule.assigneeId);

  // Any refusal from `createIssue` (for example the project's issue quota)
  // throws here, before the occurrence is recorded, so the rule stays put.
  await issueService.createIssue(actor, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId: assignee?.status === "active" ? rule.assigneeId : null,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringIssueRepo.markOccurrenceFiled(rule.orgId, rule.id, occurrence);
  return true;
}

