import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { ZodError } from "zod";
import { latestOccurrenceOn, isCalendarDate, isoWeekdayOf } from "@/lib/recurrence";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import * as recurringIssueService from "@/server/services/recurring-issue-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let free: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("recurverify", "growth");
  free = await createTenant("recurfree", "free");
});

afterAll(() => cleanup());

const base = () => ({
  orgId: tenant.org.id,
  projectId: tenant.project.id,
  title: "Daily triage",
  cadence: "daily" as const,
  weekday: null,
  timezone: "UTC",
  startsOn: "2026-03-01",
});

describe("recurring issues (temp verification)", () => {
  it("schema rules", () => {
    expect(createRecurringIssueSchema.safeParse(base()).success).toBe(true);
    expect(createRecurringIssueSchema.safeParse({ ...base(), cadence: "weekly" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base(), weekday: 3 }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base(), cadence: "weekly", weekday: 8 }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base(), timezone: "Mars/Olympus" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base(), startsOn: "2026-02-30" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base(), title: "ab" }).success).toBe(false);
    const parsed = createRecurringIssueSchema.parse({ orgId: tenant.org.id, projectId: tenant.project.id, title: "Weekly plan", cadence: "weekly", weekday: 1, timezone: "Asia/Tokyo", startsOn: "2026-03-01" });
    expect(parsed.priority).toBe("none");
    expect(parsed.assigneeId).toBeNull();
    expect(isCalendarDate("2024-02-29")).toBe(true);
    expect(isCalendarDate("2026-02-29")).toBe(false);
    expect(isoWeekdayOf("2026-03-01")).toBe(7);
  });

  it("occurrence maths incl. DST and weekly", () => {
    // 2026-03-08 is the US DST start day. 2026-03-08T06:30Z = 2026-03-08 01:30 EST? (before 2am EST->EDT) -> still 03-08 local date
    expect(latestOccurrenceOn({ cadence: "daily", weekday: null, timezone: "America/New_York", startsOn: "2026-03-01" }, new Date("2026-03-08T04:30:00Z"))).toBe("2026-03-07");
    expect(latestOccurrenceOn({ cadence: "daily", weekday: null, timezone: "America/New_York", startsOn: "2026-03-01" }, new Date("2026-03-08T05:30:00Z"))).toBe("2026-03-08");
    // Thursday weekly from 2026-03-01 (a Sunday)
    expect(latestOccurrenceOn({ cadence: "weekly", weekday: 4, timezone: "UTC", startsOn: "2026-03-01" }, new Date("2026-03-05T12:00:00Z"))).toBe("2026-03-05");
    expect(latestOccurrenceOn({ cadence: "weekly", weekday: 4, timezone: "UTC", startsOn: "2026-03-01" }, new Date("2026-03-04T23:59:00Z"))).toBe("2026-02-26"[0] ? null : null);
    expect(latestOccurrenceOn({ cadence: "weekly", weekday: 4, timezone: "UTC", startsOn: "2026-03-06" }, new Date("2026-03-11T12:00:00Z"))).toBe("2026-03-12".slice(0, 0) || null);
    // Tokyo is ahead: 2026-03-04T20:00Z = 2026-03-05 05:00 JST -> Thursday
    expect(latestOccurrenceOn({ cadence: "weekly", weekday: 4, timezone: "Asia/Tokyo", startsOn: "2026-03-01" }, new Date("2026-03-04T20:00:00Z"))).toBe("2026-03-05");
  });

  it("creates, pauses, lists, files via the job, and is idempotent", async () => {
    const created = await recurringIssueService.createRecurringIssue(tenant.actors.member, base());
    expect(created.lastOccurrenceOn).toBeNull();
    expect(created.paused).toBe(false);
    expect(created.createdBy).toBe(tenant.actors.member.userId);

    const now = new Date("2026-03-05T10:00:00Z");
    const first = await runRecurringIssueJob(now);
    expect(first.processed).toBe(1);
    expect(first.failed).toBe(0);
    const again = await runRecurringIssueJob(now);
    expect(again.processed).toBe(0);

    const [rule] = await recurringIssueService.listRecurringIssues(tenant.actors.member, tenant.org.id);
    expect(rule?.lastOccurrenceOn).toBe("2026-03-05");

    const issues = await issueRepo.listIssues({ orgId: tenant.org.id, projectId: tenant.project.id, limit: 50, includeArchived: false } as never);
    const titles = (issues as unknown as { items: { title: string; status: string; assigneeId: unknown }[] }).items.map((i) => i.title);
    expect(titles).toContain("Daily triage (2026-03-05)");

    // Missed days are not back-filled: jump 10 days ahead, one issue only.
    const later = await runRecurringIssueJob(new Date("2026-03-15T10:00:00Z"));
    expect(later.processed).toBe(1);
    const [afterLater] = await recurringIssueService.listRecurringIssues(tenant.actors.member, tenant.org.id);
    expect(afterLater?.lastOccurrenceOn).toBe("2026-03-15");

    // Pause by admin => nothing filed.
    await recurringIssueService.setRecurringIssuePaused(tenant.actors.admin, { orgId: tenant.org.id, recurringIssueId: created.id, paused: true });
    const paused = await runRecurringIssueJob(new Date("2026-03-20T10:00:00Z"));
    expect(paused.processed).toBe(0);
  });

  it("rejects over-quota, cross-tenant and bad assignees; enforces roles", async () => {
    await expect(recurringIssueService.createRecurringIssue(free.actors.member, { ...base(), orgId: free.org.id, projectId: free.project.id })).rejects.toThrow();
    await expect(recurringIssueService.createRecurringIssue(tenant.actors.member, { ...base(), orgId: free.org.id })).rejects.toThrow();
    await expect(recurringIssueService.createRecurringIssue(tenant.actors.member, { ...base(), assigneeId: "01HZZZZZZZZZZZZZZZZZZZZZZZ" as never })).rejects.toThrow();
    await expect(recurringIssueService.createRecurringIssue(tenant.actors.member, { ...base(), title: "x" })).rejects.toBeInstanceOf(ZodError);
    await expect(recurringIssueService.listRecurringIssues(tenant.actors.member, free.org.id)).rejects.toThrow();
    await expect(recurringIssueService.setRecurringIssuePaused(tenant.actors.admin, { orgId: free.org.id, recurringIssueId: "x", paused: true })).rejects.toThrow();
  });
});

